import { test, expect } from '@playwright/test';

test.describe('Timezone Setting in Profile Settings', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile/settings');
  });

  test('should successfully set timezone and display confirmation message', async ({ page }) => {
    // Verify profile settings page is loaded
    const settingsHeader = page.getByRole('heading', { name: /profile settings/i });
    await expect(settingsHeader).toBeVisible();

    // Verify timezone setting is visible
    const timezoneLabel = page.getByLabel(/timezone/i);
    await expect(timezoneLabel).toBeVisible();

    // Verify timezone dropdown exists and is not disabled
    const timezoneSelect = page.getByRole('combobox', { name: /timezone/i });
    await expect(timezoneSelect).toBeVisible();
    await expect(timezoneSelect).not.toBeDisabled();

    // Set timezone to 'America/New_York'
    await timezoneSelect.selectOption('America/New_York');

    // Click save button
    const saveButton = page.getByRole('button', { name: /save changes/i });
    await expect(saveButton).toBeVisible();
    await saveButton.click();

    // Wait for confirmation message to appear
    const confirmationMessage = page.getByText(/timezone updated successfully/i);
    await expect(confirmationMessage).toBeVisible();

    // Verify timezone value is displayed correctly
    const currentTimezoneDisplay = page.getByText('America/New_York');
    await expect(currentTimezoneDisplay).toBeVisible();

    // Verify timezone dropdown reflects the selected value
    await expect(timezoneSelect).toHaveValue('America/New_York');
  });

  test('should handle timezone setting with invalid input and display error', async ({ page }) => {
    // Verify timezone setting is visible
    const timezoneLabel = page.getByLabel(/timezone/i);
    await expect(timezoneLabel).toBeVisible();

    // Attempt to set timezone with invalid value
    const timezoneSelect = page.getByRole('combobox', { name: /timezone/i });
    await timezoneSelect.selectOption('Invalid/Timezone');

    // Click save button
    const saveButton = page.getByRole('button', { name: /save changes/i });
    await saveButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/invalid timezone value/i);
    await expect(errorMessage).toBeVisible();

    // Verify confirmation message does not appear
    const successMessage = page.getByText(/timezone updated successfully/i);
    await expect(successMessage).not.toBeVisible();

    // Verify timezone dropdown retains previous valid value
    await expect(timezoneSelect).not.toHaveValue('Invalid/Timezone');

    // Verify save button is still enabled for retry
    await expect(saveButton).not.toBeDisabled();
  });
});
